const statements = ['Ich verstehe, welche Eingabedaten erforderlich sind.', 'Ich kann die Eingabefelder leicht bearbeiten.', 'Das Dashboard stellt die Ergebnisse übersichtlich dar.', 'Ich kann die Berechnungen nachvollziehen.', 'Ich verstehe die Ampelfarben und ihre Aussagegrenzen.', 'Hinweise helfen mir, Eingabefehler zu korrigieren.', 'Das validierte Werkzeug kann die Planung unterstützen.'];
